{"cards": [{"node_code": "N_35677ff074a7e1a9", "definition": "研究铁路重载运输（如万吨列车、重载货运）的列车编组、运行图编制、牵引计算、线路通过能力及运输组织优化策略的专项管理领域。", "boundary": "本节点聚焦于“重载”这一特定工况下的运输组织与管理。边界在于区分“组织”与“装备”：机车、车辆、线路的重载工程技术归入相应技术节点；本节点侧重如何利用这些装备进行高效、安全的运输组织。若内容涉及重载列车的动力学仿真或车辆结构设计，归入车辆或线路工程；若涉及重载运输的经济效益分析，归入铁路运输经济。", "includes": ["重载列车运行图编制与优化", "重载区段通过能力计算与调度指挥策略", "重载货运组织、编组站作业流程及安全管理"], "excludes": ["重载机车、车辆、线路等基础设施的工程设计与制造技术", "重载运输的成本核算、定价及投资回报分析"], "sibling_distinctions": [{"other_code": "N_4964611f5e5d8e87", "rule": "区分依据为通用vs专项：行车组织涵盖一般铁路行车规则与流程；重载运输组织专门针对大轴重、长编组列车的特殊组织策略与能力限制。"}, {"other_code": "N_e179b2f53371fccb", "rule": "区分依据为对象特性：货物运输侧重一般货物品类的组织；重载运输组织侧重大宗散货（如煤炭、矿石）的大运量、长距离运输组织。"}], "cross_boundary_rule": "若内容涉及“重载运输技术”，若侧重列车运行控制、调度算法及组织流程，主挂载本节点；若侧重机车牵引性能、车辆结构强度或线路承载能力，归入相应工程技术节点。"}, {"node_code": "N_55566aba450aa96f", "definition": "研究铁路与其他运输方式（公路、水路、航空）或不同铁路系统之间衔接、协调、换装及全程运输组织的管理工程领域。", "boundary": "本节点聚焦于“联运”过程中的组织、协调与管理。边界在于区分“联运组织”与“单一方式运输”：纯铁路内部运输归行车组织或客货运输；纯公路或水路运输归相应方式节点。若内容涉及联运基础设施（如换装站、多式联运中心）的工程建设，归入基础设施节点；若涉及联运合同、法律及经济结算，归入铁路运输经济或法律节点。", "includes": ["铁路与公路、水路、航空等多式联运的组织流程与协调机制", "铁路国际联运的规章、作业流程及口岸交接管理", "联运货物换装、中转作业组织及全程追踪管理"], "excludes": ["单一运输方式（如纯铁路或纯公路）的内部运输组织", "联运基础设施（如码头、换装站）的工程设计与施工", "联运相关的纯经济合同、法律纠纷及财务结算"], "sibling_distinctions": [{"other_code": "N_4964611f5e5d8e87", "rule": "区分依据为范围：行车组织侧重铁路系统内部的列车运行与调度；铁路联运侧重铁路与外部系统或不同铁路系统间的衔接与协调。"}, {"other_code": "N_e179b2f53371fccb", "rule": "区分依据为环节：货物运输侧重铁路段内的货流组织；铁路联运侧重跨方式或跨系统的端到端运输组织与接口管理。"}], "cross_boundary_rule": "若内容涉及“多式联运”，若侧重运输组织、流程协调及作业衔接，主挂载本节点；若侧重联运中心、换装设施的建设，归入基础设施；若侧重联运市场分析与定价，归入铁路运输经济。"}, {"node_code": "N_cef110be32e6b02b", "definition": "研究铁路运输过程中保障行车、旅客、货物及设施安全的管理措施、事故预防、应急救援及治安维护的管理工程领域。", "boundary": "本节点聚焦于“安全”管理，包括预防、监控、应急及事后处理。边界在于区分“安全管理”与“安全技术设备”：信号联锁、车辆制动等具体设备原理归入通信信号或车辆工程；本节点侧重安全管理制度、风险评估、事故分析及救援组织。若内容涉及铁路公安的刑事侦查技术，归入公安或法律节点；若涉及纯消防工程技术，归入消防工程。", "includes": ["行车安全管理制度、风险防控及事故调查分析", "旅客与货物作业安全规范、防火安全及应急救援组织", "铁路治安维护、反恐防暴及安全管理信息系统应用"], "excludes": ["信号、通信、车辆等具体安全设备的设计、制造与维护技术", "铁路基础设施（线路、桥隧）的结构安全检测与加固工程", "纯消防工程技术或纯刑事侦查技术"], "sibling_distinctions": [{"other_code": "N_4964611f5e5d8e87", "rule": "区分依据为功能：行车组织侧重效率与秩序；安全技术侧重风险防控、事故预防及应急处理，虽涉及行车但核心目标是安全。"}, {"other_code": "N_efa4c4e2d3303a94", "rule": "区分依据为对象：旅客运输侧重服务与流程；安全技术中的旅客安全侧重人身保护、应急疏散及事故防范。"}], "cross_boundary_rule": "若内容涉及“安全监测系统”，若侧重管理决策、风险评估及制度执行，主挂载本节点；若侧重传感器原理、信号处理算法或硬件实现，归入通信信号或信息技术节点。"}]}
